/**
 * Image Color Extraction for ZX Next Palette
 * 
 * Uses Sharp for image processing to extract a palette from images.
 * 
 * Note: This is a separate module to keep image processing dependencies
 * isolated and allow for easier replacement if needed.
 */
import sharp from 'sharp';
import { PaletteColor, rgb9ToHex } from './paletteUtils';

interface RGB {
    r: number;
    g: number;
    b: number;
}

/**
 * Detect image format from magic bytes
 * @param buffer - Image data buffer
 * @returns Format name or null if not recognized
 */
function detectImageFormat(buffer: Buffer): string | null {
    // Check for minimum length
    if (buffer.length < 4) {
        return null;
    }
    
    // PNG: 89 50 4E 47 (‰PNG)
    if (buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4E && buffer[3] === 0x47) {
        return 'PNG';
    }
    
    // JPEG: FF D8 FF
    if (buffer[0] === 0xFF && buffer[1] === 0xD8 && buffer[2] === 0xFF) {
        return 'JPEG';
    }
    
    // GIF: 47 49 46 38 (GIF8)
    if (buffer[0] === 0x47 && buffer[1] === 0x49 && buffer[2] === 0x46 && buffer[3] === 0x38) {
        return 'GIF';
    }
    
    // BMP: 42 4D (BM)
    if (buffer[0] === 0x42 && buffer[1] === 0x4D) {
        return 'BMP';
    }
    
    // WEBP: Check for WEBP within RIFF header (8-12 bytes)
    if (buffer.length >= 12 && 
        buffer[0] === 0x52 && buffer[1] === 0x49 && buffer[2] === 0x46 && buffer[3] === 0x46 && // RIFF
        buffer[8] === 0x57 && buffer[9] === 0x45 && buffer[10] === 0x42 && buffer[11] === 0x50) { // WEBP
        return 'WEBP';
    }
    
    // TIFF: 49 49 2A 00 (little endian) or 4D 4D 00 2A (big endian)
    if ((buffer[0] === 0x49 && buffer[1] === 0x49 && buffer[2] === 0x2A && buffer[3] === 0x00) ||
        (buffer[0] === 0x4D && buffer[1] === 0x4D && buffer[2] === 0x00 && buffer[3] === 0x2A)) {
        return 'TIFF';
    }
    
    return null;
}

/**
 * Manual BMP Parser Interface
 */
interface BmpInfo {
    width: number;
    height: number;
    bitDepth: number;
    rgbaData: Buffer;
}

/**
 * Manual BMP parser for cases where Sharp can't handle the BMP format
 * @param fileData - BMP file data
 * @returns Promise with BMP info and RGBA data
 */
async function parseBmpManually(fileData: Uint8Array): Promise<BmpInfo> {
    if (fileData.length < 54) {
        throw new Error('Invalid BMP: File too small');
    }
    
    // Check BMP signature
    if (fileData[0] !== 0x42 || fileData[1] !== 0x4D) { // 'BM'
        throw new Error('Invalid BMP: Missing BM signature');
    }
    
    // Read BMP header (little-endian)
    const pixelDataOffset = readUint32LE(fileData, 10);
    const width = readInt32LE(fileData, 18);
    const height = readInt32LE(fileData, 22);
    const bitDepth = readUint16LE(fileData, 28);
    const compression = readUint32LE(fileData, 30);
    
    console.log(`[BMP Parser] ${width}x${height}, ${bitDepth}-bit, compression: ${compression}`);
    
    // Only support uncompressed BMPs for now
    if (compression !== 0) {
        throw new Error(`Unsupported BMP compression: ${compression}`);
    }
    
    // Calculate row stride (rows are padded to 4-byte boundary)
    const bytesPerPixel = bitDepth / 8;
    const rowStride = Math.floor((width * bytesPerPixel + 3) / 4) * 4;
    
    // Create RGBA buffer
    const rgbaData = Buffer.alloc(width * Math.abs(height) * 4);
    let rgbaIndex = 0;
    
    // BMPs can have negative height (top-down) or positive (bottom-up)
    const isTopDown = height < 0;
    const absHeight = Math.abs(height);
    
    if (bitDepth === 8) {
        // 8-bit indexed color format - read color palette first
        const paletteSize = 256;
        const paletteOffset = 54; // After DIB header
        const palette: {r: number, g: number, b: number}[] = [];
        
        // Read color palette (256 entries of 4 bytes each: BGRA)
        for (let i = 0; i < paletteSize; i++) {
            const paletteIndex = paletteOffset + i * 4;
            if (paletteIndex + 3 >= fileData.length) {
                break;
            }
            
            const b = fileData[paletteIndex];
            const g = fileData[paletteIndex + 1];
            const r = fileData[paletteIndex + 2];
            // Skip alpha byte at paletteIndex + 3
            
            palette.push({ r, g, b });
        }
        
        // Read indexed pixel data
        for (let y = 0; y < absHeight; y++) {
            const srcY = isTopDown ? y : (absHeight - 1 - y);
            const rowOffset = pixelDataOffset + srcY * rowStride;
            
            for (let x = 0; x < width; x++) {
                const pixelOffset = rowOffset + x;
                if (pixelOffset >= fileData.length) {
                    break;
                }
                
                // Get palette index
                const paletteIndex = fileData[pixelOffset];
                
                // Look up color in palette
                if (paletteIndex < palette.length) {
                    const color = palette[paletteIndex];
                    rgbaData[rgbaIndex++] = color.r;
                    rgbaData[rgbaIndex++] = color.g;
                    rgbaData[rgbaIndex++] = color.b;
                    rgbaData[rgbaIndex++] = 255; // Alpha
                } else {
                    // Invalid palette index, use black
                    rgbaData[rgbaIndex++] = 0;
                    rgbaData[rgbaIndex++] = 0;
                    rgbaData[rgbaIndex++] = 0;
                    rgbaData[rgbaIndex++] = 255;
                }
            }
        }
    } else if (bitDepth === 24) {
        // 24-bit BGR format
        for (let y = 0; y < absHeight; y++) {
            const srcY = isTopDown ? y : (absHeight - 1 - y);
            const rowOffset = pixelDataOffset + srcY * rowStride;
            
            for (let x = 0; x < width; x++) {
                const pixelOffset = rowOffset + x * 3;
                if (pixelOffset + 2 >= fileData.length) {
                    break;
                }
                
                // BMP stores as BGR, convert to RGBA
                const b = fileData[pixelOffset];
                const g = fileData[pixelOffset + 1];
                const r = fileData[pixelOffset + 2];
                
                rgbaData[rgbaIndex++] = r;
                rgbaData[rgbaIndex++] = g;
                rgbaData[rgbaIndex++] = b;
                rgbaData[rgbaIndex++] = 255; // Alpha
            }
        }
    } else if (bitDepth === 32) {
        // 32-bit BGRA format
        for (let y = 0; y < absHeight; y++) {
            const srcY = isTopDown ? y : (absHeight - 1 - y);
            const rowOffset = pixelDataOffset + srcY * rowStride;
            
            for (let x = 0; x < width; x++) {
                const pixelOffset = rowOffset + x * 4;
                if (pixelOffset + 3 >= fileData.length) {
                    break;
                }
                
                // BMP stores as BGRA, convert to RGBA
                const b = fileData[pixelOffset];
                const g = fileData[pixelOffset + 1];
                const r = fileData[pixelOffset + 2];
                const a = fileData[pixelOffset + 3];
                
                rgbaData[rgbaIndex++] = r;
                rgbaData[rgbaIndex++] = g;
                rgbaData[rgbaIndex++] = b;
                rgbaData[rgbaIndex++] = a;
            }
        }
    } else {
        throw new Error(`Unsupported BMP bit depth: ${bitDepth}. Only 8-bit, 24-bit and 32-bit BMPs are supported.`);
    }
    
    return {
        width,
        height: absHeight,
        bitDepth,
        rgbaData
    };
}

// Helper methods for reading little-endian values
function readUint16LE(buffer: Uint8Array, offset: number): number {
    return buffer[offset] | (buffer[offset + 1] << 8);
}

function readUint32LE(buffer: Uint8Array, offset: number): number {
    return buffer[offset] | (buffer[offset + 1] << 8) | (buffer[offset + 2] << 16) | (buffer[offset + 3] << 24);
}

function readInt32LE(buffer: Uint8Array, offset: number): number {
    const uint = readUint32LE(buffer, offset);
    return uint > 0x7FFFFFFF ? uint - 0x100000000 : uint;
}

/**
 * Extract colo rs from an image file
 * 
 * @param imageData - The raw image data as Uint8Array
 * @param maxColors - Maximum number of colors to extract (default: 256)
 * @returns Promise resolving to an array of PaletteColor objects
 */
export async function extractColorsFromImage(imageData: Uint8Array, maxColors: number = 256): Promise<PaletteColor[]> {
    try {
        // Check if the image data is valid and detect format
        const imageBuffer = Buffer.from(imageData);
        
        // Basic validation - check minimum file size
        if (imageBuffer.length < 8) {
            throw new Error('File is too small to be a valid image');
        }
        
        // Check magic bytes to detect image format
        const format = detectImageFormat(imageBuffer);
        console.log(`Detected image format: ${format || 'unknown'}`);
        
        if (!format) {
            throw new Error('Unrecognized image format. Please use PNG, JPEG, GIF, BMP, or WEBP images.');
        }
        
        // Try Sharp first, but fall back to manual BMP parser if needed
        let pixelBuffer: Buffer;
        let info: { width: number; height: number; channels: number };
        
        if (format === 'BMP') {
            // Try Sharp first for BMP, but be ready to fall back to manual parser
            try {
                const sharpInstance = sharp(imageBuffer, { 
                    failOn: 'none',
                    limitInputPixels: false,
                    sequentialRead: true
                });
                
                const metadata = await sharpInstance.metadata();
                console.log(`BMP metadata via Sharp: ${metadata.width}x${metadata.height}, format: ${metadata.format}`);
                
                const result = await sharpInstance
                    .ensureAlpha()
                    .raw()
                    .toBuffer({ resolveWithObject: true });
                    
                pixelBuffer = result.data;
                info = result.info;
                console.log('Successfully processed BMP with Sharp');
                
            } catch (sharpError) {
                console.log('Sharp failed for BMP, trying manual parser:', sharpError);
                // Fall back to manual BMP parser
                const bmpResult = await parseBmpManually(new Uint8Array(imageBuffer));
                pixelBuffer = bmpResult.rgbaData;
                info = {
                    width: bmpResult.width,
                    height: bmpResult.height,
                    channels: 4
                };
                console.log(`Successfully processed BMP with manual parser: ${info.width}x${info.height}`);
            }
        } else {
            // For non-BMP formats, use Sharp normally
            try {
                const sharpInstance = sharp(imageBuffer, { 
                    failOn: 'none',
                    limitInputPixels: false,
                    sequentialRead: true
                });
                
                const metadata = await sharpInstance.metadata();
                console.log(`Image metadata: ${metadata.width}x${metadata.height}, format: ${metadata.format}, channels: ${metadata.channels}`);
                
                if (!metadata.width || !metadata.height) {
                    throw new Error('Invalid image: Could not determine image dimensions');
                }
                
                const result = await sharpInstance
                    .ensureAlpha()
                    .raw()
                    .toBuffer({ resolveWithObject: true });
                    
                pixelBuffer = result.data;
                info = result.info;
                
            } catch (metadataError) {
                console.error('Sharp metadata error:', metadataError);
                throw new Error(`Unsupported image format or corrupted image file. Sharp error: ${metadataError instanceof Error ? metadataError.message : String(metadataError)}`);
            }
        }
        
        const width = info.width;
        const height = info.height;
        
        // Map to store unique colors
        const colorMap = new Map<string, RGB>();
        
        // Scan image pixels (RGBA format - 4 bytes per pixel)
        for (let i = 0; i < pixelBuffer.length; i += 4) {
            const r = pixelBuffer[i];
            const g = pixelBuffer[i + 1];
            const b = pixelBuffer[i + 2];
            const a = pixelBuffer[i + 3];
            
            // Skip transparent pixels
            if (a < 128) {
                continue;
            }
            
            // Create RGB object
            const rgb = { r, g, b };
            
            // Create a key for the color map
            const colorKey = `${r},${g},${b}`;
            
            // Add to map if not exists
            if (!colorMap.has(colorKey)) {
                colorMap.set(colorKey, rgb);
            }
        }
        
        console.log(`Extracted ${colorMap.size} unique colors from image`);
        
        // Convert to array of RGB values
        let colors = Array.from(colorMap.values());
        
        // If we have too many colors, quantize them
        if (colors.length > maxColors) {
            colors = quantizeColors(colors, maxColors);
            console.log(`Quantized to ${colors.length} colors`);
        }
        
        // Convert to ZX Next PaletteColor format
        const paletteColors: PaletteColor[] = colors.map(rgb => {
            // Convert 8-bit RGB to 3-bit per channel (9-bit RGB)
            const r9 = Math.round((rgb.r / 255) * 7);
            const g9 = Math.round((rgb.g / 255) * 7);
            const b9 = Math.round((rgb.b / 255) * 7);
            
            // Convert to hex using the utility function
            const hex = rgb9ToHex(r9, g9, b9);
            
            return { hex, priority: false };
        });
        
        return paletteColors;
    } catch (error) {
        console.error('Error extracting colors from image:', error);
        
        // Provide more helpful error messages
        if (error instanceof Error) {
            if (error.message.includes('Input buffer contains unsupported image format')) {
                throw new Error('The image format is not supported. Please try with PNG, JPEG, GIF, or BMP images.');
            } else if (error.message.includes('Input file contains unsupported image format')) {
                throw new Error('The image file format is not recognized. Please ensure the file is a valid image (PNG, JPEG, GIF, BMP).');
            } else if (error.message.includes('Input file is missing')) {
                throw new Error('The image file appears to be empty or corrupted.');
            } else {
                // Re-throw with the original message for other errors
                throw new Error(`Image processing failed: ${error.message}`);
            }
        } else {
            throw new Error(`Image processing failed: ${String(error)}`);
        }
    }
}

/**
 * Simple color quantization using median cut algorithm
 * 
 * @param colors - Array of RGB colors
 * @param targetCount - Target number of colours
 * @returns Array of quantized RGB colors
 */
function quantizeColors(colors: RGB[], targetCount: number): RGB[] {
    if (colors.length <= targetCount) {
        return colors;
    }
    
    // Start with all colors in one bucket
    const buckets: RGB[][] = [colors];
    
    // Split buckets until we have enough
    while (buckets.length < targetCount) {
        // Find the bucket with the largest range
        let largestRangeIndex = 0;
        let largestRange = 0;
        
        for (let i = 0; i < buckets.length; i++) {
            const bucket = buckets[i];
            if (bucket.length <= 1) continue; // Can't split further
            
            // Find the component with the largest range
            let rMin = 255, rMax = 0, gMin = 255, gMax = 0, bMin = 255, bMax = 0;
            
            for (const color of bucket) {
                rMin = Math.min(rMin, color.r);
                rMax = Math.max(rMax, color.r);
                gMin = Math.min(gMin, color.g);
                gMax = Math.max(gMax, color.g);
                bMin = Math.min(bMin, color.b);
                bMax = Math.max(bMax, color.b);
            }
            
            const rRange = rMax - rMin;
            const gRange = gMax - gMin;
            const bRange = bMax - bMin;
            
            const bucketRange = Math.max(rRange, gRange, bRange);
            
            if (bucketRange > largestRange) {
                largestRange = bucketRange;
                largestRangeIndex = i;
            }
        }
        
        // If we can't split any further, break
        if (largestRange === 0) break;
        
        // Split the bucket along the component with the largest range
        const bucketToSplit = buckets[largestRangeIndex];
        
        // Determine the component to sort by
        let sortComponent: 'r' | 'g' | 'b';
        let rMin = 255, rMax = 0, gMin = 255, gMax = 0, bMin = 255, bMax = 0;
        
        for (const color of bucketToSplit) {
            rMin = Math.min(rMin, color.r);
            rMax = Math.max(rMax, color.r);
            gMin = Math.min(gMin, color.g);
            gMax = Math.max(gMax, color.g);
            bMin = Math.min(bMin, color.b);
            bMax = Math.max(bMax, color.b);
        }
        
        const rRange = rMax - rMin;
        const gRange = gMax - gMin;
        const bRange = bMax - bMin;
        
        if (rRange >= gRange && rRange >= bRange) {
            sortComponent = 'r';
        } else if (gRange >= rRange && gRange >= bRange) {
            sortComponent = 'g';
        } else {
            sortComponent = 'b';
        }
        
        // Sort by the selected component
        bucketToSplit.sort((a, b) => a[sortComponent] - b[sortComponent]);
        
        // Split at median
        const medianIndex = Math.floor(bucketToSplit.length / 2);
        const lowerHalf = bucketToSplit.slice(0, medianIndex);
        const upperHalf = bucketToSplit.slice(medianIndex);
        
        // Replace the bucket with the two halves
        buckets.splice(largestRangeIndex, 1, lowerHalf, upperHalf);
    }
    
    // Extract the average color from each bucket
    return buckets.map(bucket => {
        if (bucket.length === 0) {
            return { r: 0, g: 0, b: 0 }; // Default black if empty bucket
        }
        
        if (bucket.length === 1) {
            return bucket[0]; // Return single color
        }
        
        // Calculate average color for bucket
        let rSum = 0, gSum = 0, bSum = 0;
        
        for (const color of bucket) {
            rSum += color.r;
            gSum += color.g;
            bSum += color.b;
        }
        
        return {
            r: Math.round(rSum / bucket.length),
            g: Math.round(gSum / bucket.length),
            b: Math.round(bSum / bucket.length)
        };
    });
} 